if(ui.modal==='share'){let h=historyById(ui.shareActivityId);if(!h){ui.modal=null;renderModal();return}html=overlay('Partager ma séance',`<div class="share-options">${[['poster','Affiche sportive'],['transparent','Fond transparent'],['photo','Sur une photo'],['detail','Récap détaillé']].map(([id,label])=>`<button class="${ui.shareMode===id?'active':''}" data-a="share-style" data-id="${id}">${label}</button>`).join('')}</div><div class="segmented">${[['story','Story 9:16'],['post','Publication 4:5']].map(([id,label])=>`<button class="${ui.shareFormat===id?'active':''}" data-a="share-format" data-id="${id}">${label}</button>`).join('')}</div>${ui.shareMode==='photo'?`<div class="field" style="margin-bottom:10px"><label>PHOTO DE L'IPHONE</label><input type="file" id="share-photo" accept="image/*"></div>`:''}<div class="share-preview"><canvas id="shareCanvas" width="1080" height="1920" aria-label="Aperçu export Instagram"></canvas></div><div class="hint" style="text-align:center;margin:8px 0">Aperçu exportable à tout moment depuis cette activité.</div>`,`<div class="row"><button class="btn outline" style="flex:1" data-a="download-share">⇩ PNG</button><button class="btn primary" style="flex:1" data-a="native-share">↗ PARTAGER</button></div>`);}
