function editValueFromField(el){let s=ui.editDraft;if(!s)return;let type=el.dataset.ed,i=Number(el.dataset.i),j=Number(el.dataset.j),f=el.dataset.f;if(type==='sessionname')s.name=el.value;else if(type==='sessionday')s.day=el.value;else if(type==='exname'){let e=s.exercises[i],l=byName(el.value);e.name=el.value;e.primary=clone(l.primary);e.secondary=clone(l.secondary);e.tip=l.tip}else if(type==='set')s.exercises[i].sets[j][f]=Math.max(0,Number(el.value)||0)}
